"""Variant of sep2 with resize + signal + scripted-action support. Do not modify sep2/an."""
import os,pty,fcntl,termios,struct,subprocess,time,select,signal,sys
EXE=os.environ.get('EXE','/workspace/executable')

def run(args=(),cols=80,rows=24,json_in=None,script=(),wait=0.45,key_delay=0.18,
        final_wait=0.4,term='xterm-256color',exe=None,env=None,mark=True):
    """script: list of items.
         bytes            -> write to master, then pump(key_delay)
         ('w',b'..',t)    -> write, pump t
         ('resize',c,r)   -> TIOCSWINSZ on master (kernel sends SIGWINCH), pump key_delay
         ('resize',c,r,t) -> same with explicit pump
         ('sig',SIG)      -> send signal to child pgid, pump key_delay
         ('sleep',t)      -> pump t
       Returns (stdout, stderr, rc, marks) where marks is a list of
       (index, len(stdout) BEFORE the action) so output can be attributed.
    """
    master,slave=pty.openpty()
    fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',rows,cols,0,0))
    a=termios.tcgetattr(slave)
    a[1] &= ~(termios.ONLCR|termios.OPOST)
    a[3] &= ~(termios.ECHO|termios.ECHONL|termios.ICANON|termios.ISIG|termios.IEXTEN)
    a[0] &= ~(termios.ICRNL|termios.INLCR|termios.IGNCR|termios.IXON)
    termios.tcsetattr(slave,termios.TCSANOW,a)
    e=dict(os.environ); e['TERM']=term
    if env: e.update(env)
    err,ew=os.pipe()
    inr=inw=None
    if json_in is not None: inr,inw=os.pipe()
    def setup(): os.setsid(); fcntl.ioctl(slave,termios.TIOCSCTTY,0)
    p=subprocess.Popen([exe or EXE]+[str(x) for x in args],
        stdin=(inr if inr is not None else slave),stdout=slave,stderr=ew,
        env=e,close_fds=True,preexec_fn=setup)
    os.close(slave);os.close(ew)
    if inr is not None: os.close(inr);os.write(inw,json_in);os.close(inw)
    for f in (master,err): fcntl.fcntl(f,fcntl.F_SETFL,fcntl.fcntl(f,fcntl.F_GETFL)|os.O_NONBLOCK)
    O=bytearray();E=bytearray()
    def pump(t):
        end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([master,err],[],[],0.02)
            for f in r:
                try:d=os.read(f,1<<16)
                except Exception:d=b''
                (O if f==master else E).extend(d)
    pump(wait)
    marks=[('start',len(O),None)]
    for i,item in enumerate(script):
        t=key_delay
        if isinstance(item,(bytes,bytearray)):
            marks.append((i,len(O),('w',bytes(item))))
            try:os.write(master,bytes(item))
            except Exception as ex: pass
        elif isinstance(item,str):
            marks.append((i,len(O),('w',item.encode())))
            try:os.write(master,item.encode())
            except Exception: pass
        else:
            op=item[0]
            if op=='w':
                marks.append((i,len(O),item)); t=item[2] if len(item)>2 else key_delay
                try:os.write(master,item[1])
                except Exception: pass
            elif op=='resize':
                c,r=item[1],item[2]; t=item[3] if len(item)>3 else key_delay
                marks.append((i,len(O),item))
                fcntl.ioctl(master,termios.TIOCSWINSZ,struct.pack('HHHH',r,c,0,0))
            elif op=='sig':
                marks.append((i,len(O),item)); t=item[2] if len(item)>2 else key_delay
                try:os.killpg(os.getpgid(p.pid),item[1])
                except Exception: pass
            elif op=='sleep':
                marks.append((i,len(O),item)); t=item[1]
            elif op=='poll':
                marks.append((i,len(O),('poll',p.poll())) ); t=0
            else: raise ValueError(op)
        pump(t)
    pump(final_wait)
    rc=p.poll()
    killed=False
    if rc is None:
        killed=True
        try:os.killpg(os.getpgid(p.pid),signal.SIGKILL)
        except Exception:pass
        try:p.wait(timeout=3)
        except Exception:pass
    for f in (master,err):
        try:os.close(f)
        except Exception:pass
    marks.append(('end',len(O),('killed',killed)))
    return bytes(O),bytes(E),rc,marks

# ---- mouse helpers -----------------------------------------------------
def sgr(btn,col,row,press=True):
    return ('\x1b[<%d;%d;%d%s'%(btn,col,row,'M' if press else 'm')).encode()
def click(col,row,btn=0):
    return [sgr(btn,col,row,True),sgr(btn,col,row,False)]

import re,sys
ANSI=re.compile(rb'\x1b(\[[0-9;\-\? ]*[A-Za-z]|P[^\x1b]*\x1b\\|\][^\x07]*\x07|.)')

def chunks(o):
    return o.split(b'\x00')

def frames(o):
    """all NUL-delimited chunks; returns list of (index, bytes)."""
    return list(enumerate(o.split(b'\x00')))

def is_frame(c):
    return c.endswith(b'\x1b[?25l')

def grid(frame):
    b=frame
    b=re.sub(rb'^(\x1b\[\d+[BC])*',b'',b)
    b=re.sub(rb'^\r(\x1b\[2K|\x1b\[1A)*',b'',b)
    b=re.sub(rb'^\x1b\[6n',b'',b)
    m=re.search(rb'(\x1b\[-?\d+A)?(\x1b\[-?\d+D)?\x1b\[\?25[lh]$',b)
    tail=b''
    if m:
        tail=b[m.start():]
        b=b[:m.start()]
    plain=ANSI.sub(b'',b)
    rows=plain.split(b'\r\n')
    return rows,tail

def cursor(rows,tail):
    m1=re.search(rb'\x1b\[(-?\d+)A',tail); m2=re.search(rb'\x1b\[(-?\d+)D',tail)
    dy=int(m1.group(1)) if m1 else 0
    dx=int(m2.group(1)) if m2 else 0
    dimy=len(rows); dimx=max(len(r) for r in rows) if rows else 0
    return dimx,dimy,dx,dy,(dimx-dx,dimy-1-dy)

def sel(frame):
    """return list of (rowidx, text) for rows containing the reverse-video run"""
    b=frame
    m=re.search(rb'(\x1b\[-?\d+A)?(\x1b\[-?\d+D)?\x1b\[\?25[lh]$',b)
    if m: b=b[:m.start()]
    b=re.sub(rb'^(\x1b\[\d+[BC])*',b'',b)
    b=re.sub(rb'^\r(\x1b\[2K|\x1b\[1A)*',b'',b)
    b=re.sub(rb'^\x1b\[6n',b'',b)
    out=[]
    for i,line in enumerate(b.split(b'\r\n')):
        for mm in re.finditer(rb'\x1b\[7m(.*?)\x1b\[27m',line,re.S):
            txt=ANSI.sub(b'',mm.group(1)).rstrip()
            # column = plain length of prefix
            col=len(ANSI.sub(b'',line[:mm.start()]))
            out.append((i,col,txt.decode('utf8','replace')))
    return out

def dump(o,marks=None,label='',maxframes=200,text=True):
    cs=o.split(b'\x00')
    # offsets of each chunk start
    offs=[];p=0
    for c in cs:
        offs.append(p); p+=len(c)+1
    mi=0
    print('####',label)
    for i,c in enumerate(cs):
        note=''
        if marks:
            evs=[m for m in marks if offs[i] <= m[1] < offs[i]+len(c)+1]
        print(' -- chunk %d len=%d %s'%(i,len(c),note))
        if i<2 or not is_frame(c):
            print('    RAW',repr(c[:400]))
            continue
        rr,tl=grid(c)
        dimx,dimy,dx,dy,cur=cursor(rr,tl)
        print('    dim=%dx%d dx=%d dy=%d cursor=%s sel=%s'%(dimx,dimy,dx,dy,cur,sel(c)))
        if text:
            for r in rr: print('     |'+r.decode('utf8','replace').rstrip()+'|')

def summary(o,label=''):
    """compact: per frame, selection + dims"""
    cs=o.split(b'\x00')
    out=[]
    for i,c in enumerate(cs):
        if i<2 or not is_frame(c): continue
        rr,tl=grid(c)
        dimx,dimy,dx,dy,cur=cursor(rr,tl)
        out.append((i,dimx,dimy,cur,sel(c)))
    if label: print('##',label)
    for t in out: print('   frame chunk=%d dim=%dx%d cur=%s sel=%s'%t)
    return out

def attribute(o,marks):
    """map each output chunk to the action that preceded it"""
    cs=o.split(b'\x00')
    offs=[];p=0
    for c in cs:
        offs.append(p);p+=len(c)+1
    res=[]
    for i,c in enumerate(cs):
        # last mark with pos <= offs[i]
        act=None
        for m in marks:
            if m[1]<=offs[i]: act=m
        res.append((i,act,c))
    return res
